# No imports, same complexity
def are_anagrams_manual(s1, s2):
    if len(s1) != len(s2):
        return False

    counts = {}
    for c in s1:
        counts[c] = counts.get(c, 0) + 1
    for c in s2:
        counts[c] = counts.get(c, 0) - 1
        if counts[c] < 0:
            return False

    return True

# If you need in-place / O(1) extra space and can modify inputs
def are_anagrams_sorted(s1, s2):
    return sorted(s1) == sorted(s2)  # O(n log n) time, O(1) or O(n) space
```

The `Counter` approach is the pragmatic default: clean, fast, and handles Unicode correctly without extra work.

